<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Forms;

use Override;
use Psr\Http\Message\ResponseInterface;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepName;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\OAuth\MagicLink\Application\Usecase\RequestMagicLink\RequestMagicLinkUsecase;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

/**
 * Login step form that handles passwordless authentication via magic links sent by email.
 *
 * This form implements a two-page flow within the magic-link step. On the first page the user
 * enters their email address; the form then calls RequestMagicLinkUsecase to dispatch a
 * one-time sign-in link to that address and throws a LoginException carrying the
 * ERR_MAGIC_LINK_SENT result to signal the waiting state. On subsequent renders, detecting
 * that same error code, it swaps in a confirmation page that instructs the user to check
 * their inbox.
 *
 * The actual link-click verification is handled by a separate endpoint; this form only covers
 * the request-and-wait phase of the interaction.
 *
 * Relationships: delegates magic-link dispatch to RequestMagicLinkUsecase, uses DecorateHtml
 * for themed page rendering, HtmlSecurer for CSRF signing scripts, and MessageProvider for
 * translated labels.
 */
class MagicLinkLoginForm implements StepForm
{
    public function __construct(
        private readonly MessageProvider $messages,
        private readonly RequestMagicLinkUsecase $requestMagicLink,
        private readonly DecorateHtml $decorator,
        private readonly HtmlSecurer $securer,
    ) {
    }

    /**
     * Renders either the email-entry form or the confirmation page, depending on the current error state.
     *
     * When the error indicates the magic link has already been sent (ERR_MAGIC_LINK_SENT), the
     * confirmation page is shown. Otherwise the email-entry form is rendered with CSRF and
     * auto-focus scripts injected.
     */
    #[Override]
    public function render(StepInput $input, ResponseInterface $response, ?AuthenticationResult $error): StepResult
    {
        $locale = '';
        $tenant = $input->context->tenant;
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        if ($error?->error === AuthenticationResult::ERR_MAGIC_LINK_SENT) {
            $response->getBody()->write($this->decorator->getFullPage(
                $input->request,
                $translator->get('magic-link.sent.title'),
                $this->buildConfirmHtml($translator),
                $locale,
                'index',
                $tenant,
            ));
            return StepResult::render($response, $input->challenges);
        }

        $js = $this->securer->configureScripts([
            $this->securer->addSign('sign'),
            $this->securer->focusOn('email'),
        ]);

        $response->getBody()->write($this->decorator->getFullPage(
            $input->request,
            $translator->get('magic-link.ask.title'),
            $js . $this->buildAskHtml($translator),
            $locale,
            'index',
            $tenant,
        ));
        return StepResult::render($response, $input->challenges);
    }

    /**
     * Processes the submitted email and triggers the magic-link dispatch.
     *
     * Calls RequestMagicLinkUsecase with the tenant and OAuth flow context, then always throws
     * a LoginException carrying AuthenticationResult::waitMagicLink() to transition the UI to
     * the confirmation page on the next render cycle.
     */
    #[Override]
    public function authenticate(StepInput $input): StepResult
    {
        $email = (string) ($input->body['email'] ?? '');

        $this->requestMagicLink->request(
            email: $email,
            clientId: $input->authRequest->client->id,
            redirectUri: $input->authRequest->redirect,
            tenantName: $input->context->tenant,
            scope: $input->authRequest->scope,
            state: $input->context->state !== '' ? $input->context->state : null,
            nonce: $input->context->nonce,
        );

        throw new LoginException(AuthenticationResult::waitMagicLink());
    }

    private function buildAskHtml(object $translator): string
    {
        $step = StepName::MAGIC_LINK->value;
        $title = $translator->get('magic-link.ask.title');
        $help = $translator->get('magic-link.ask.help');
        $emailLabel = $translator->get('magic-link.ask.email');
        $send = $translator->get('magic-link.ask.send');
        $backText = $translator->get(
            'magic-link.ask.back-text',
            ['<input class="inline" type="submit" value="' . $translator->get('magic-link.ask.back-label') . '" />'],
        );

        return <<<HTML
            <h1>{$title}</h1>
            <p>{$help}</p>
            <form method="POST">
                <input type="hidden" name="csid" id="sign" />
                <input type="hidden" name="step" value="{$step}" />
                <label>{$emailLabel}
                    <input type="email" name="email" id="email" value="" autocomplete="email" />
                </label>
                <input class="primary-button" type="submit" value="{$send}" />
            </form>
            <form method="POST">
                <input type="hidden" name="step" value="" />
                {$backText}
            </form>
            HTML;
    }

    private function buildConfirmHtml(object $translator): string
    {
        $title = $translator->get('magic-link.sent.title');
        $help = $translator->get('magic-link.sent.help');
        $backText = $translator->get(
            'magic-link.sent.back-text',
            ['<input class="inline" type="submit" value="' . $translator->get('magic-link.sent.back-label') . '" />'],
        );

        return <<<HTML
            <h1>{$title}</h1>
            <p>{$help}</p>
            <form method="POST">
                <input type="hidden" name="step" value="" />
                {$backText}
            </form>
            HTML;
    }
}
